367	// CreateInvite invites an email address to join an organization with a role.
368	func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
369		email = strings.TrimSpace(email)
370		if !validEmail(email) {
371			return Invite{}, invalid("an invite needs a valid email address")
372		}
373		if !role.Valid() || role == RoleOwner {
374			return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
375		}
376		s.mu.Lock()
377		defer s.mu.Unlock()
378		if _, ok := s.orgs[orgID]; !ok {
379			return Invite{}, ErrNotFound
380		}
381		if uid, ok := s.usersByEmail[normEmail(email)]; ok {
382			if _, member := s.members[memberKey{orgID, uid}]; member {
383				return Invite{}, ErrAlreadyMember
384			}
385		}
386		inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, Token: NewToken("invite_"), InvitedBy: invitedBy, CreatedAt: now.UTC()}
387		s.invites[inv.ID] = inv
388		return inv, nil
389	}
