374	// ---- invites
375	
376	// NewInviteToken returns 32 random bytes from crypto/rand, in unpadded base64url.
377	func NewInviteToken() string {
378		b := make([]byte, 32)
379		if _, err := rand.Read(b); err != nil {
380			panic(err) // crypto/rand does not fail on supported platforms
381		}
382		return base64.RawURLEncoding.EncodeToString(b)
383	}
384	
385	// hashToken is what the store keeps of an invite's token.
386	func hashToken(token string) string {
387		h := sha256.Sum256([]byte(token))
388		return hex.EncodeToString(h[:])
389	}
390	
391	// expired reports whether the invite's token no longer works at now.
392	func (inv Invite) expired(now time.Time) bool { return now.After(inv.ExpiresAt) }
393	
394	// CreateInvite invites an email address to join an organization with a role. It revokes the address's earlier open invites
395	// to the organization, so only the new invite's token works. The returned invite carries the token, which the store does not keep.
396	func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
397		email = strings.TrimSpace(email)
398		if !validEmail(email) {
399			return Invite{}, invalid("an invite needs a valid email address")
400		}
401		if !role.Valid() || role == RoleOwner {
402			return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
403		}
404		s.mu.Lock()
405		defer s.mu.Unlock()
406		if _, ok := s.orgs[orgID]; !ok {
407			return Invite{}, ErrNotFound
408		}
409		if uid, ok := s.usersByEmail[normEmail(email)]; ok {
410			if _, member := s.members[memberKey{orgID, uid}]; member {
411				return Invite{}, ErrAlreadyMember
412			}
413		}
414		for id, old := range s.invites {
415			if old.OrgID == orgID && normEmail(old.Email) == normEmail(email) && old.AcceptedAt == nil && old.RevokedAt == nil {
416				t := now.UTC()
417				old.RevokedAt = &t
418				s.invites[id] = old
419			}
420		}
421		token := NewInviteToken()
422		created := now.UTC()
423		inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, TokenHash: hashToken(token), InvitedBy: invitedBy,
424			CreatedAt: created, ExpiresAt: created.Add(InviteLifetime)}
425		s.invites[inv.ID] = inv
426		inv.Token = token
427		return inv, nil
428	}
429	
430	// Invite returns one of an organization's invites.
431	func (s *Store) Invite(orgID, id string) (Invite, bool) {
432		s.mu.Lock()
433		defer s.mu.Unlock()
434		inv, ok := s.invites[id]
435		if !ok || inv.OrgID != orgID {
436			return Invite{}, false
437		}
438		return inv, true
439	}
440	
441	// Invites returns an organization's invites that were neither accepted nor revoked, oldest first. Unlike PendingInvites,
442	// it includes expired ones.
443	func (s *Store) Invites(orgID string) []Invite {
444		s.mu.Lock()
445		defer s.mu.Unlock()
446		out := []Invite{}
447		for _, inv := range s.invites {
448			if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil {
449				out = append(out, inv)
450			}
451		}
452		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
453		return out
454	}
455	
456	// PendingInvites returns an organization's invites that are neither accepted, revoked nor expired at now, oldest first.
457	func (s *Store) PendingInvites(orgID string, now time.Time) []Invite {
458		s.mu.Lock()
459		defer s.mu.Unlock()
460		out := []Invite{}
461		for _, inv := range s.invites {
462			if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil && !inv.expired(now) {
463				out = append(out, inv)
464			}
465		}
466		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
467		return out
468	}
469	
470	// RevokeInvite withdraws an invite.
471	func (s *Store) RevokeInvite(orgID, id string, now time.Time) (Invite, error) {
472		s.mu.Lock()
473		defer s.mu.Unlock()
474		inv, ok := s.invites[id]
475		if !ok || inv.OrgID != orgID {
476			return Invite{}, ErrNotFound
477		}
478		if inv.RevokedAt == nil {
479			t := now.UTC()
480			inv.RevokedAt = &t
481			s.invites[id] = inv
482		}
483		return inv, nil
484	}
485	
486	// AcceptInvite accepts the invite with this token: it finds or creates the user for the invited address (named name),
487	// makes them a member with the invite's role and gives them a first API key. A token that is unknown or revoked is
488	// ErrNotFound, one that was already used is ErrInviteUsed, and one older than InviteLifetime is ErrInviteExpired.
489	func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
490		s.mu.Lock()
491		defer s.mu.Unlock()
492		var inv Invite
493		found := false
494		if token != "" {
495			h := hashToken(token)
496			for _, i := range s.invites {
497				if i.TokenHash == h {
498					inv, found = i, true
499					break
500				}
501			}
502		}
503		if !found || inv.RevokedAt != nil {
504			return User{}, Member{}, APIKey{}, ErrNotFound
505		}
506		if inv.AcceptedAt != nil {
507			return User{}, Member{}, APIKey{}, ErrInviteUsed
508		}
509		if inv.expired(now) {
510			return User{}, Member{}, APIKey{}, ErrInviteExpired
