376	// NewInviteToken returns 32 random bytes from crypto/rand, in unpadded base64url.
377	func NewInviteToken() string {
378		b := make([]byte, 32)
379		if _, err := rand.Read(b); err != nil {
380			panic(err) // crypto/rand does not fail on supported platforms
381		}
382		return base64.RawURLEncoding.EncodeToString(b)
383	}
384	
385	// hashToken is what the store keeps of an invite's token.
386	func hashToken(token string) string {
387		h := sha256.Sum256([]byte(token))
388		return hex.EncodeToString(h[:])
389	}
