391	// expired reports whether the invite's token no longer works at now.
392	func (inv Invite) expired(now time.Time) bool { return now.After(inv.ExpiresAt) }
393	
394	// CreateInvite invites an email address to join an organization with a role. It revokes the address's earlier open invites
395	// to the organization, so only the new invite's token works. The returned invite carries the token, which the store does not keep.
396	func (s *Store) CreateInvite(orgID, email string, role Role, invitedBy string, now time.Time) (Invite, error) {
397		email = strings.TrimSpace(email)
398		if !validEmail(email) {
399			return Invite{}, invalid("an invite needs a valid email address")
400		}
401		if !role.Valid() || role == RoleOwner {
402			return Invite{}, invalid("an invite's role is admin, billing, member or viewer")
403		}
404		s.mu.Lock()
405		defer s.mu.Unlock()
406		if _, ok := s.orgs[orgID]; !ok {
407			return Invite{}, ErrNotFound
408		}
409		if uid, ok := s.usersByEmail[normEmail(email)]; ok {
410			if _, member := s.members[memberKey{orgID, uid}]; member {
411				return Invite{}, ErrAlreadyMember
412			}
413		}
414		for id, old := range s.invites {
415			if old.OrgID == orgID && normEmail(old.Email) == normEmail(email) && old.AcceptedAt == nil && old.RevokedAt == nil {
416				t := now.UTC()
417				old.RevokedAt = &t
418				s.invites[id] = old
419			}
420		}
421		token := NewInviteToken()
422		created := now.UTC()
423		inv := Invite{ID: s.newID("inv"), OrgID: orgID, Email: email, Role: role, TokenHash: hashToken(token), InvitedBy: invitedBy,
424			CreatedAt: created, ExpiresAt: created.Add(InviteLifetime)}
425		s.invites[inv.ID] = inv
426		inv.Token = token
427		return inv, nil
428	}
