430	// Invite returns one of an organization's invites.
431	func (s *Store) Invite(orgID, id string) (Invite, bool) {
432		s.mu.Lock()
433		defer s.mu.Unlock()
434		inv, ok := s.invites[id]
435		if !ok || inv.OrgID != orgID {
436			return Invite{}, false
437		}
438		return inv, true
439	}
