441	// Invites returns an organization's invites that were neither accepted nor revoked, oldest first. Unlike PendingInvites,
442	// it includes expired ones.
443	func (s *Store) Invites(orgID string) []Invite {
444		s.mu.Lock()
445		defer s.mu.Unlock()
446		out := []Invite{}
447		for _, inv := range s.invites {
448			if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil {
449				out = append(out, inv)
450			}
451		}
452		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
453		return out
454	}
455	
456	// PendingInvites returns an organization's invites that are neither accepted, revoked nor expired at now, oldest first.
457	func (s *Store) PendingInvites(orgID string, now time.Time) []Invite {
458		s.mu.Lock()
459		defer s.mu.Unlock()
460		out := []Invite{}
461		for _, inv := range s.invites {
462			if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil && !inv.expired(now) {
463				out = append(out, inv)
464			}
465		}
466		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
467		return out
468	}
