470	// RevokeInvite withdraws an invite.
471	func (s *Store) RevokeInvite(orgID, id string, now time.Time) (Invite, error) {
472		s.mu.Lock()
473		defer s.mu.Unlock()
474		inv, ok := s.invites[id]
475		if !ok || inv.OrgID != orgID {
476			return Invite{}, ErrNotFound
477		}
478		if inv.RevokedAt == nil {
479			t := now.UTC()
480			inv.RevokedAt = &t
481			s.invites[id] = inv
482		}
483		return inv, nil
484	}
