146	func (s *Server) createInvite(w http.ResponseWriter, r *http.Request, p auth.Principal) {
147		if !auth.CanManageTeam(p.Role) {
148			writeError(w, http.StatusForbidden, "forbidden", "only owners and admins invite members")
149			return
150		}
151		var in struct {
152			Email string     `json:"email"`
153			Role  store.Role `json:"role"`
154		}
155		if !decode(w, r, &in) {
156			return
157		}
158		inv, err := s.store.CreateInvite(p.OrgID, in.Email, in.Role, p.UserID, s.clock.Now())
159		if err != nil {
160			s.storeError(w, err)
161			return
162		}
163		if err := s.sendInvite(r.Context(), inv); err != nil {
164			s.log.Error("send invite", "invite", inv.ID, "err", err)
165		}
166		writeJSON(w, http.StatusCreated, inviteViewOf(inv))
167	}
