175			Subject: fmt.Sprintf("You are invited to join %s on Tally", o.Name),
176			Body:    fmt.Sprintf("You have been invited to join %s on Tally as %s.\n\nAccept the invitation: %s\n", o.Name, inv.Role, link),
177		})
